<script setup lang="ts">
import { computed } from 'vue'; import { addUnit } from '../../libs';
import type { SnakeSwiperEmits, SnakeSwiperItem, SnakeSwiperProps } from './types';
const props=withDefaults(defineProps<SnakeSwiperProps>(),{list:()=>[],current:0,height:300,autoplay:true,interval:3000,duration:300,circular:true,indicator:false,name:'url',radius:0,previousMargin:'0px',nextMargin:'0px',imgMode:'aspectFill',showTitle:false}); const emit=defineEmits<SnakeSwiperEmits>(); const source=(item:SnakeSwiperItem)=>typeof item==='string'?item:String(item?.[props.name]??item?.src??item?.url??''); const title=(item:SnakeSwiperItem)=>typeof item==='string'?'':String(item?.title??item?.text??''); const style=computed(()=>({height:addUnit(props.height,'rpx'),borderRadius:addUnit(props.radius,'rpx'),overflow:'hidden'})); function change(e:any){emit('change',{current:e.detail.current})}
</script>
<template><view class="snake-swiper" :style="[$snakeThemeStyle, style]"><swiper class="snake-swiper__body" :current="current" :autoplay="autoplay" :interval="interval" :duration="duration" :circular="circular" :indicator-dots="indicator" :previous-margin="previousMargin" :next-margin="nextMargin" @change="change"><swiper-item v-for="(item,index) in list" :key="index" @click="emit('click',index)"><image class="snake-swiper__image" :src="source(item)" :mode="imgMode as any"/><text v-if="showTitle && title(item)" class="snake-swiper__title">{{title(item)}}</text></swiper-item></swiper><view class="snake-swiper__indicator"><slot name="indicator" /></view></view></template>
<style scoped>.snake-swiper,.snake-swiper__body,.snake-swiper__image{position:relative;width:100%;height:100%}.snake-swiper__title{position:absolute;right:0;bottom:0;left:0;padding:16rpx 20rpx;color:var(--snake-color-white,#fff);background:rgba(0,0,0,.45)}.snake-swiper__indicator{position:absolute;right:0;bottom:14rpx;left:0}</style>
